mapper.select:
SELECT DISTINCT SUBSTRING_INDEX( eet.`NAME`, '-', - 1 ) AS `name`, er.`application_code` as `application_name`, er.`enabled` FROM `emergency_event_type` eet INNER JOIN `emergency_rule` er ON er.`emergency_event_type_code` = eet.`code` WHERE 1=1
and er.`application_code` IN
#{code}
AND SUBSTRING_INDEX( eet.`NAME`, '-', - 1 ) IN
#{alarmEvent}
